Hey all — adding the minimal SDK snippet and recommended defaults below so Sofia's engineers can hit the ground running. I'll paste as plain text for copy/paste.

--- sample Node.js snippet ---
const fetch = require('node-fetch');
const API_KEY = process.env.REDWOOD_API_KEY;

async function generate(prompt) {
  const resp = await fetch('https://api.redwood.com/v1/generate', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ prompt }),
    timeout: 20000 // ms
  });
  if (!resp.ok) throw new Error(`status=${resp.status}`);
  return resp.json();
}

// Recommended client-side policies:
// - Timeout: 20s for generate calls (increase for long chains)
// - Retries: up to 4 attempts with exponential backoff and full jitter (base 200ms)
// - Rate limits: honor 429; on 429 backoff and throttle to half of previous concurrency
// - Batching: prefer batch endpoints for embeddings to reduce token-unit cost

